def _parse_data_hex(v, counts):
    if type(v) is not str:
        raise Bad()
    n = len(v)
    if n > LIM_HEXCHARS or (n & 1) or not HEX_RE.match(v):
        raise Bad()
    data = bytes.fromhex(v)
    counts[3] += n // 2
    if counts[3] > LIM_DATA:
        raise Bad()
    return data


FRAME_TYPES = ("PADDING", "PING", "ACK", "CRYPTO", "STREAM", "RESET_STREAM",
               "STOP_SENDING", "CLOSE", "HANDSHAKE_DONE", "UNKNOWN")
FRAME_TYPES = frozenset(FRAME_TYPES)


def _parse_frame(f, counts):
    if type(f) is not dict:
        raise Bad()
    ty = f.get("type")
    if type(ty) is not str or ty not in FRAME_TYPES:
        raise Bad()
    if ty == "PADDING":
        _keys_exact(f, ("type",))
        return ("pad",)
    if ty == "PING":
        _keys_exact(f, ("type",))
        return ("ping",)
    if ty == "UNKNOWN":
        _keys_exact(f, ("type",))
        return ("un",)
    if ty == "HANDSHAKE_DONE":
        _keys_exact(f, ("type",))
        return ("hd",)
    if ty == "ACK":
        _keys_exact(f, ("type", "ranges"))
        return ("ack", tuple(_parse_ranges_shape(f["ranges"])))
    if ty == "CRYPTO":
        _keys_exact(f, ("type", "offset", "data_hex"))
        off = f["offset"]
        if not _dom_int(off):
            raise Bad()
        return ("cry", off, _parse_data_hex(f["data_hex"], counts))
    if ty == "STREAM":
        _keys_exact(f, ("type", "id", "offset", "data_hex", "fin"))
        sid = f["id"]
        off = f["offset"]
        if not _dom_int(sid) or not _dom_int(off):
            raise Bad()
        if type(f["fin"]) is not bool:
            raise Bad()
        return ("str", sid, off, _parse_data_hex(f["data_hex"], counts),
                f["fin"])
    if ty == "RESET_STREAM":
        _keys_exact(f, ("type", "id", "final_size"))
        sid = f["id"]
        size = f["final_size"]
        if not _dom_int(sid) or not _dom_int(size):
            raise Bad()
        return ("rs", sid, size)
    if ty == "STOP_SENDING":
        _keys_exact(f, ("type", "id"))
        sid = f["id"]
        if not _dom_int(sid):
            raise Bad()
        return ("ss", sid)
    # CLOSE
    _keys_exact(f, ("type", "app", "code"))
    if type(f["app"]) is not bool:
        raise Bad()
